:root{--color-primary-dark:#9b2c1c;--color-primary-darker:#7a2114;--color-accent-on-dark:#f6c667;--color-bg:#ffffff;--color-bg-alt:#1a1a1a;--color-bg-soft:#f7f3f0;--color-text:#222222;--color-text-light:#ffffff;--color-border:#e0e0e0;--font-main:Arial, Helvetica, sans-serif;--font-heading:Impact, 'Arial Black', sans-serif;--space-sm:0.5rem;--space-md:1rem;--space-lg:2rem;--space-xl:4rem;--radius:0.4rem;}
*{box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{margin:0;font-family:var(--font-main);color:var(--color-text);background:var(--color-bg);line-height:1.6;}
h1,h2,h3{font-family:var(--font-heading);line-height:1.2;margin-top:0;}
a{color:var(--color-primary-dark);text-decoration:underline;}
a:focus,button:focus,input:focus,textarea:focus,select:focus{outline:3px solid var(--color-accent-on-dark);outline-offset:2px;}
.container{max-width:75rem;margin:0 auto;padding:0 1rem;width:100%;}

/* Header */
header{background:var(--color-bg);border-bottom:1px solid var(--color-border);}
header .container{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;padding-top:1rem;padding-bottom:1rem;gap:1rem;}
.logo{font-family:var(--font-heading);text-transform:uppercase;letter-spacing:0.05em;color:var(--color-primary-dark);text-decoration:none;font-size:clamp(1.1rem,4vw,1.6rem);text-shadow:2px 2px 0 var(--color-accent-on-dark);transform:skew(-6deg);display:inline-block;}
@media (prefers-reduced-motion: reduce){.logo{transition:none;}}
nav[aria-label='Main'] ul{list-style:none;display:flex;flex-wrap:wrap;gap:1rem;margin:0;padding:0;}
nav[aria-label='Main'] a{color:var(--color-text);text-decoration:none;font-weight:bold;padding:0.3rem 0.2rem;}
nav[aria-label='Main'] a:hover{color:var(--color-primary-dark);text-decoration:underline;}

/* Footer */
footer{background:var(--color-bg-alt);color:var(--color-text-light);padding:var(--space-lg) 0;margin-top:var(--space-xl);}
footer .footer-logo{font-family:var(--font-heading);color:var(--color-accent-on-dark);font-size:1.3rem;text-transform:uppercase;letter-spacing:0.05em;margin-bottom:0.5rem;}
footer p{margin:0.3rem 0;}

/* Buttons */
.btn{display:inline-block;min-height:44px;padding:0.7rem 1.5rem;background:var(--color-primary-dark);color:var(--color-text-light);border:none;border-radius:var(--radius);font-weight:bold;font-size:1rem;text-decoration:none;cursor:pointer;text-align:center;}
.btn:hover{background:var(--color-primary-darker);}
.btn-outline{background:transparent;border:2px solid var(--color-text-light);color:var(--color-text-light);}
.btn-outline:hover{background:var(--color-text-light);color:var(--color-primary-dark);}

/* Cards */
.card{background:var(--color-bg-soft);border:1px solid var(--color-border);border-radius:var(--radius);padding:var(--space-lg);}
.card h3{color:var(--color-primary-dark);}

/* Grid helper */
.grid{display:grid;gap:var(--space-lg);grid-template-columns:1fr;}

/* Forms */
form{display:flex;flex-direction:column;gap:var(--space-md);max-width:34rem;}
label{font-weight:bold;margin-bottom:0.3rem;display:block;}
input,textarea,select{width:100%;min-height:44px;padding:0.5rem 0.7rem;border:1px solid var(--color-border);border-radius:var(--radius);font-size:1rem;font-family:inherit;}
textarea{min-height:120px;}

/* Section helpers (shared, page adds its own) */
section{padding:var(--space-xl) 0;}
section.dark{background:var(--color-bg-alt);color:var(--color-text-light);}
section.dark h2{color:var(--color-accent-on-dark);}
section.soft{background:var(--color-bg-soft);}

/* Mobile breakpoint */
@media (max-width:600px){
  header .container{flex-direction:column;align-items:flex-start;}
  nav[aria-label='Main'] ul{flex-direction:column;gap:0.5rem;width:100%;}
  .container{padding:0 1rem;}
  .grid{grid-template-columns:1fr;}
  .logo{font-size:1.2rem;}
}

/* Desktop breakpoint */
@media (min-width:601px){
  .grid-2{grid-template-columns:repeat(2,1fr);}
  .grid-3{grid-template-columns:repeat(3,1fr);}
  .grid-4{grid-template-columns:repeat(4,1fr);}
  nav[aria-label='Main'] ul{flex-direction:row;}
}

pages.css:
.index-hero{background:linear-gradient(rgba(26,26,26,0.75),rgba(26,26,26,0.75)),url('https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=1200&q=80') center/cover no-repeat;color:var(--color-text-light);padding:var(--space-xl) 0;min-height:60vh;display:flex;align-items:center;}
.index-hero-content{max-width:40rem;}
.index-hero-content h1{color:var(--color-text-light);font-size:clamp(2rem,6vw,3.2rem);margin-bottom:var(--space-md);}
.index-hero-text{font-size:1.1rem;margin-bottom:var(--space-lg);}
.index-about-grid{margin-top:var(--space-lg);}
.index-plans-grid{margin-top:var(--space-lg);align-items:stretch;}
.index-plan-card{display:flex;flex-direction:column;justify-content:space-between;text-align:center;}
.index-plan-price{font-size:1.8rem;font-weight:bold;color:var(--color-primary-dark);margin:var(--space-sm) 0;}
.index-plan-popular{border:3px solid var(--color-primary-dark);}
.index-plan-list{list-style:none;padding:0;margin:var(--space-md) 0;text-align:left;}
.index-plan-list li{padding:0.3rem 0;border-bottom:1px solid var(--color-border);}
.index-testimonials-grid{margin-top:var(--space-lg);}
.index-testimonial{background:var(--color-bg-alt);border:1px solid var(--color-accent-on-dark);color:var(--color-text-light);margin:0;}
.index-testimonial p{font-style:italic;}
.index-testimonial footer{margin-top:var(--space-sm);font-weight:bold;color:var(--color-accent-on-dark);}
.index-join-content{max-width:40rem;}
.index-join-form div{width:100%;}
@media (max-width:600px){
  .index-hero{min-height:50vh;text-align:center;}
  .index-hero-content{margin:0 auto;}
  .index-plan-popular{border-width:2px;}
}
@media (min-width:601px){
  .index-hero-content{padding-left:var(--space-lg);}
}

